### 2. Migration Tests
```typescript
// src/lib/db/__tests__/migrations.test.ts
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import { testDb, resetTestDatabase } from '@/test/db';

describe('Database Migrations', () => {
  beforeAll(async () => {
    await resetTestDatabase();
  });

  it('should run all migrations without error', async () => {
    await expect(
      migrate(testDb, { migrationsFolder: './drizzle' })
    ).resolves.not.toThrow();
  });

  it('should create all expected tables', async () => {
    const result = await testDb.execute(sql\`
      SELECT table_name FROM information_schema.tables 
      WHERE table_schema = 'public'
    \`);

    const tables = result.rows.map(r => r.table_name);
    expect(tables).toContain('users');
    expect(tables).toContain('forms');
    expect(tables).toContain('questions');
    expect(tables).toContain('responses');
  });
});
```

### 3. CRUD Operation Tests
```typescript
// src/lib/db/__tests__/operations.test.ts
import { describe, it, expect, beforeEach } from 'vitest';
import { testDb, resetTestDatabase } from '@/test/db';
import { users, workspaces, forms, questions } from '../schema';
import { eq } from 'drizzle-orm';

describe('Database Operations', () => {
  beforeEach(async () => {
    await resetTestDatabase();
  });

  describe('Users', () => {
    it('should create a user', async () => {
      const [user] = await testDb.insert(users).values({
        email: 'test@example.com',
        name: 'Test User',
      }).returning();

      expect(user.id).toBeDefined();
      expect(user.email).toBe('test@example.com');
    });

    it('should enforce unique email constraint', async () => {
      await testDb.insert(users).values({
        email: 'duplicate@example.com',
        name: 'User 1',
      });

      await expect(
        testDb.insert(users).values({
          email: 'duplicate@example.com',
          name: 'User 2',
        })
      ).rejects.toThrow();
    });
  });

  describe('Forms', () => {
    it('should create form with workspace relation', async () => {
      const [user] = await testDb.insert(users).values({
        email: 'owner@example.com',
        name: 'Owner',
      }).returning();

      const [workspace] = await testDb.insert(workspaces).values({
        name: 'Test Workspace',
        slug: 'test-workspace',
        ownerId: user.id,
      }).returning();

      const [form] = await testDb.insert(forms).values({
        workspaceId: workspace.id,
        createdBy: user.id,
        title: 'Test Form',
        slug: 'test-form',
      }).returning();

      expect(form.workspaceId).toBe(workspace.id);
      expect(form.status).toBe('draft');
    });

    it('should cascade delete questions when form deleted', async () => {
      // Create form with questions, delete form, verify questions deleted
    });
  });
});
```

