## Logic Engine Implementation

```typescript
// src/lib/logic/engine.ts
export class LogicEngine {
  private form: Form;
  private questions: Question[];
  private responses: Record<string, any>;
  private variables: Record<string, any>;

  constructor(form: Form, questions: Question[]) {
    this.form = form;
    this.questions = questions;
    this.responses = {};
    this.variables = {};
  }

  // Evaluate a single condition
  evaluateCondition(condition: LogicCondition): boolean {
    const value = this.getValue(condition.field);

    switch (condition.operator) {
      case 'equals':
        return value === condition.value;
      case 'not_equals':
        return value !== condition.value;
      case 'contains':
        return String(value).includes(condition.value);
      case 'greater_than':
        return Number(value) > Number(condition.value);
      // ... more operators
    }
  }

  // Evaluate multiple conditions with AND/OR
  evaluateConditions(conditions: LogicCondition[], operator: 'and' | 'or'): boolean {
    if (operator === 'and') {
      return conditions.every(c => this.evaluateCondition(c));
    }
    return conditions.some(c => this.evaluateCondition(c));
  }

  // Get next question based on logic
  getNextQuestion(currentQuestionId: string): string | null {
    const currentQuestion = this.questions.find(q => q.id === currentQuestionId);

    // Check skip logic
    if (currentQuestion?.logicJump) {
      const skipLogic = currentQuestion.logicJump as SkipLogic;
      if (this.evaluateConditions(skipLogic.conditions, skipLogic.operator)) {
        if (skipLogic.action.type === 'end_form') {
          return null; // Go to thank you screen
        }
        return skipLogic.action.targetQuestionId;
      }
    }

    // Default: next visible question
    return this.getNextVisibleQuestion(currentQuestionId);
  }

  // Get visible questions based on show/hide logic
  getVisibleQuestions(): Question[] {
    return this.questions.filter(q => {
      if (!q.visibilityLogic) return true;
      const logic = q.visibilityLogic as VisibilityLogic;
      return this.evaluateConditions(logic.showIf, logic.operator);
    });
  }

  // Interpolate piping tokens in text
  interpolate(text: string): string {
    return text.replace(/\{\{(\w+)\}\}/g, (match, id) => {
      return this.getValue(id) || match;
    });
  }

  // Calculate scores
  calculateScore(calculatorId: string): number {
    const calculator = this.form.calculators.find(c => c.id === calculatorId);
    if (!calculator) return 0;

    return calculator.variables.reduce((sum, variable) => {
      const answer = this.responses[variable.questionId];
      const score = variable.optionScores?.[answer] || variable.defaultValue || 0;
      return sum + score;
    }, 0);
  }
}
```

## UI Components

### Logic Builder Modal
```typescript
function LogicBuilderModal({ question, onSave }: LogicBuilderProps) {
  const [conditions, setConditions] = useState<LogicCondition[]>([]);
  const [operator, setOperator] = useState<'and' | 'or'>('and');
  const [action, setAction] = useState<LogicAction>({ type: 'jump_to' });

  return (
    <Dialog>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Add Logic</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div className="font-medium">If...</div>

          {conditions.map((condition, index) => (
            <ConditionRow
              key={index}
              condition={condition}
              questions={questions}
              onChange={(c) => updateCondition(index, c)}
              onRemove={() => removeCondition(index)}
            />
          ))}

          <div className="flex gap-2">
            <Button variant="outline" onClick={addCondition}>
              <PlusIcon /> Add condition
            </Button>

            {conditions.length > 1 && (
              <Select value={operator} onValueChange={setOperator}>
                <SelectItem value="and">AND</SelectItem>
                <SelectItem value="or">OR</SelectItem>
              </Select>
            )}
          </div>

          <div className="font-medium">Then...</div>

          <ActionSelector action={action} onChange={setAction} questions={questions} />
        </div>

        <DialogFooter>
          <Button onClick={() => onSave({ conditions, operator, action })}>
            Save Logic
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
```

### Piping Textarea
```typescript
function PipingTextarea({ value, onChange, questions }: PipingTextareaProps) {
  const [showMentions, setShowMentions] = useState(false);
  const [mentionQuery, setMentionQuery] = useState('');

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === '@') {
      setShowMentions(true);
    }
  };

  const insertMention = (questionId: string) => {
    const newValue = value.replace(/@\w*$/, `{{$\{questionId}}}`);
    onChange(newValue);
    setShowMentions(false);
  };

  return (
    <div className="relative">
      <Textarea
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={handleKeyDown}
      />

      {showMentions && (
        <MentionPopover
          query={mentionQuery}
          questions={questions}
          onSelect={insertMention}
          onClose={() => setShowMentions(false)}
        />
      )}
    </div>
  );
}
```

