// src/lib/email/index.ts
import { Resend } from 'resend';

const resend = new Resend(process.env.RESEND_API_KEY);

export async function sendEmail(notification: EmailNotification) {
  const template = emailTemplates[notification.type];

  const html = await renderEmailTemplate(template.template, notification.data);

  await resend.emails.send({
    from: 'noreply@example.com',
    to: notification.to,
    subject: interpolate(template.subject, notification.data),
    html,
  });
}

