### 6. Webhook System
```typescript
interface Webhook {
  id: string;
  formId: string;
  url: string;
  secret?: string;
  events: WebhookEvent[];
  isActive: boolean;
  headers?: Record<string, string>;
  createdAt: Date;
}

type WebhookEvent = 
  | 'response.created'
  | 'response.completed'
  | 'response.updated'
  | 'form.published'
  | 'form.closed';

// Webhook payload
interface WebhookPayload {
  event: WebhookEvent;
  timestamp: string;
  data: {
    formId: string;
    formTitle: string;
    response?: Response;
  };
  signature?: string;
}

// Send webhook
async function sendWebhook(webhook: Webhook, payload: WebhookPayload) {
  const signature = webhook.secret 
    ? createHmac('sha256', webhook.secret).update(JSON.stringify(payload)).digest('hex')
    : undefined;

  try {
    const response = await fetch(webhook.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Webhook-Signature': signature || '',
        ...webhook.headers,
      },
      body: JSON.stringify(payload),
    });

    // Log webhook delivery
    await logWebhookDelivery(webhook.id, {
      status: response.status,
      responseBody: await response.text(),
    });
  } catch (error) {
    await logWebhookDelivery(webhook.id, {
      status: 0,
      error: error.message,
    });
  }
}
```

