// src/lib/permissions.ts
export function hasPermission(
  member: WorkspaceMember,
  permission: string
): boolean {
  const permissions = rolePermissions[member.role];
  return permissions.includes('*') || permissions.includes(permission);
}

// Hook for components
export function usePermission(permission: string): boolean {
  const { currentMember } = useWorkspace();
  return hasPermission(currentMember, permission);
}

// Server-side check
export async function checkPermission(
  workspaceId: string,
  userId: string,
  permission: string
): Promise<boolean> {
  const member = await getMember(workspaceId, userId);
  if (!member) return false;
  return hasPermission(member, permission);
}

