### 2. API Authentication Middleware
```typescript
// src/lib/api/auth.ts
export async function authenticateApiRequest(request: Request): Promise<ApiAuthResult> {
  const authHeader = request.headers.get('Authorization');

  if (!authHeader) {
    return { authenticated: false, error: 'Missing Authorization header' };
  }

  // Bearer token (API key)
  if (authHeader.startsWith('Bearer ')) {
    const key = authHeader.slice(7);
    return await validateApiKey(key);
  }

  // OAuth token
  if (authHeader.startsWith('OAuth ')) {
    const token = authHeader.slice(6);
    return await validateOAuthToken(token);
  }

  return { authenticated: false, error: 'Invalid Authorization format' };
}

async function validateApiKey(key: string): Promise<ApiAuthResult> {
  const hash = crypto.createHash('sha256').update(key).digest('hex');

  const apiKey = await db.query.apiKeys.findFirst({
    where: eq(apiKeys.keyHash, hash),
    with: { workspace: true },
  });

  if (!apiKey) {
    return { authenticated: false, error: 'Invalid API key' };
  }

  if (apiKey.expiresAt && apiKey.expiresAt < new Date()) {
    return { authenticated: false, error: 'API key expired' };
  }

  // Update last used
  await db.update(apiKeys)
    .set({ lastUsedAt: new Date() })
    .where(eq(apiKeys.id, apiKey.id));

  return {
    authenticated: true,
    workspaceId: apiKey.workspaceId,
    permissions: apiKey.permissions,
  };
}
```

### 3. Rate Limiting
```typescript
import { Ratelimit } from '@upstash/ratelimit';
import { Redis } from '@upstash/redis';

const ratelimit = new Ratelimit({
  redis: Redis.fromEnv(),
  limiter: Ratelimit.slidingWindow(100, '1 m'), // 100 requests per minute
  analytics: true,
});

export async function checkRateLimit(identifier: string): Promise<RateLimitResult> {
  const { success, limit, remaining, reset } = await ratelimit.limit(identifier);

  return {
    allowed: success,
    headers: {
      'X-RateLimit-Limit': limit.toString(),
      'X-RateLimit-Remaining': remaining.toString(),
      'X-RateLimit-Reset': reset.toString(),
    },
  };
}

// Middleware wrapper
export function withRateLimit(handler: Handler): Handler {
  return async (request: Request) => {
    const auth = await authenticateApiRequest(request);
    if (!auth.authenticated) {
      return Response.json({ error: auth.error }, { status: 401 });
    }

    const rateLimit = await checkRateLimit(auth.workspaceId);
    if (!rateLimit.allowed) {
      return Response.json(
        { error: 'Rate limit exceeded' },
        { status: 429, headers: rateLimit.headers }
      );
    }

    const response = await handler(request);
    // Add rate limit headers to response
    return new Response(response.body, {
      ...response,
      headers: { ...response.headers, ...rateLimit.headers },
    });
  };
}
```

