          canGoBack={state.currentQuestionIndex > 0}
          canGoNext={!currentQuestion.required || state.answers[currentQuestion.id]}
          onBack={() => dispatch({ type: 'GO_BACK' })}
          onNext={() => dispatch({ type: 'GO_NEXT' })}
          isLastQuestion={state.currentQuestionIndex === visibleQuestions.length - 1}
        />

        <KeyboardHints question={currentQuestion} />
      </div>
    </ThemeProvider>
  );
}
