### 4. Keyboard Navigation
```typescript
// src/hooks/useFormKeyboard.ts
export function useFormKeyboard({
  question,
  onNext,
  onBack,
  onSelect,
  onSubmit,
}: FormKeyboardOptions) {
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Enter to continue
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        onNext();
      }

      // Shift+Enter for new line (in text areas)
      // Arrow keys for navigation
      if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
        // Previous option or go back
      }
      if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
        // Next option
      }

      // Letter keys for quick selection (A, B, C...)
      if (question.type === 'multiple_choice') {
        const index = e.key.toUpperCase().charCodeAt(0) - 65;
        if (index >= 0 && index < question.options.length) {
          onSelect(question.options[index].id);
        }
      }

      // Y/N for yes/no questions
      if (question.type === 'yes_no') {
        if (e.key.toLowerCase() === 'y') onSelect(true);
        if (e.key.toLowerCase() === 'n') onSelect(false);
      }

      // Escape to go back
      if (e.key === 'Escape') {
        onBack();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [question, onNext, onBack, onSelect]);
}
```

