  }, []);

  return (
    <motion.div
      initial={{ scale: 0.9, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      className="success-screen"
    >
      <CheckCircleIcon className="w-16 h-16 text-green-500" />
      <h1>{form.thankYouScreen?.title || 'Thank you!'}</h1>
      <p>{form.thankYouScreen?.description || 'Your response has been recorded.'}</p>

      {form.thankYouScreen?.showSocialShare && (
        <SocialShareButtons url={window.location.href} />
      )}

      {form.thankYouScreen?.buttonUrl && (
        <Button asChild>
          <a href={form.thankYouScreen.buttonUrl}>
            {form.thankYouScreen.buttonText || 'Continue'}
          </a>
        </Button>
      )}
    </motion.div>
  );
}
