// Different limits for different endpoints
const limits = {
  'POST /api/auth/login': { requests: 5, window: '15m' },
  'POST /api/forms': { requests: 100, window: '1h' },
  'POST /api/responses': { requests: 1000, window: '1h' },
  'default': { requests: 100, window: '1m' },
};

// IP-based + user-based limiting
async function rateLimit(request: Request, identifier: string) {
  const ip = getClientIp(request);

  // Check both IP and user limits
  const [ipLimit, userLimit] = await Promise.all([
    checkLimit(`ip:${ip}`),
    checkLimit(`user:${identifier}`),
  ]);

  return ipLimit.allowed && userLimit.allowed;
}
