## Component Architecture
```typescript
// Question option type
interface QuestionOption {
  id: string;
  label: string;
  value?: string;
  image?: string;
  order: number;
}

// Renderer component example
export function MultipleChoiceQuestion({ question, value, onChange }: QuestionProps) {
  const settings = question.settings as MultipleChoiceSettings;
  const options = settings.randomize 
    ? shuffleArray(settings.options) 
    : settings.options;

  return (
    <RadioGroup value={value} onValueChange={onChange}>
      {options.map((option, index) => (
        <div key={option.id} className="flex items-center space-x-2">
          <RadioGroupItem value={option.id} id={option.id} />
          <Label htmlFor={option.id}>
            <span className="shortcut">{String.fromCharCode(65 + index)}</span>
            {option.label}
          </Label>
        </div>
      ))}
      {settings.allowOther && (
        <OtherOption value={value} onChange={onChange} />
      )}
    </RadioGroup>
  );
}
```

