## Keyboard Shortcuts
```typescript
// src/hooks/useQuestionShortcuts.ts
export function useQuestionShortcuts(options: QuestionOption[], onSelect: (id: string) => void) {
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const index = e.key.toUpperCase().charCodeAt(0) - 65; // A=0, B=1, etc.
      if (index >= 0 && index < options.length) {
        onSelect(options[index].id);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [options, onSelect]);
}
```

