### Video Embed
```typescript
import ReactPlayer from 'react-player';

export function VideoEmbed({ question, onContinue }: ContentBlockProps) {
  const settings = question.settings as VideoEmbedSettings;
  const [canContinue, setCanContinue] = useState(!settings.requiredWatchTime);
  const [watchedSeconds, setWatchedSeconds] = useState(0);

  const handleProgress = ({ playedSeconds }: { playedSeconds: number }) => {
    setWatchedSeconds(playedSeconds);
    if (settings.requiredWatchTime && playedSeconds >= settings.requiredWatchTime) {
      setCanContinue(true);
    }
  };

  return (
    <div className="video-embed">
      <ReactPlayer
        url={settings.url}
        playing={settings.autoplay}
        controls={settings.showControls}
        loop={settings.loop}
        muted={settings.muted}
        onProgress={handleProgress}
        width="100%"
        height="auto"
      />

      {settings.requiredWatchTime && !canContinue && (
        <p className="text-sm text-muted">
          Watch for {settings.requiredWatchTime - Math.floor(watchedSeconds)}s to continue
        </p>
      )}

      <Button onClick={onContinue} disabled={!canContinue}>
        Continue
      </Button>
    </div>
  );
}
```

