// src/lib/versions.ts
export async function saveVersion(formId: string, description?: string) {
  const form = await getFormWithQuestions(formId);

  return await db.insert(formVersions).values({
    formId,
    version: await getNextVersion(formId),
    snapshot: {
      title: form.title,
      description: form.description,
      settings: form.settings,
      questions: form.questions,
    },
    createdBy: getCurrentUserId(),
  });
}

export async function restoreVersion(formId: string, versionId: string) {
  const version = await db.query.formVersions.findFirst({
    where: eq(formVersions.id, versionId),
  });

  // Save current as new version first
  await saveVersion(formId, 'Before restore');

  // Restore from snapshot
  await applySnapshot(formId, version.snapshot);
}
```

