async function detectSpam(response: Response): Promise<{
  isSpam: boolean;
  confidence: number;
  reasons: string[];
}> {
  // Check for patterns
  const checks = [
    checkForGibberish(response),
    checkForRepetition(response),
    checkSubmissionSpeed(response),
    checkForLinks(response),
  ];

  // AI-based check for sophisticated spam
  const aiCheck = await aiSpamCheck(response);

  return combineChecks([...checks, aiCheck]);
}
