### 1. CSV Export
```typescript
interface ExportOptions {
  format: 'csv' | 'excel' | 'pdf' | 'json';
  includeMetadata: boolean;
  dateFormat: string;
  questionIds?: string[]; // Specific questions only
  responseIds?: string[]; // Specific responses only
  filters?: ResponseFilters;
}

async function exportToCSV(formId: string, options: ExportOptions) {
  const responses = await fetchResponses(formId, options.filters);
  const questions = await fetchQuestions(formId);

  // Build header row
  const headers = [
    'Response ID',
    'Submitted At',
    ...questions.map(q => q.title),
    ...(options.includeMetadata ? ['IP Address', 'Device', 'Country'] : []),
  ];

  // Build data rows
  const rows = responses.map(response => [
    response.id,
    formatDate(response.completedAt, options.dateFormat),
    ...questions.map(q => formatAnswer(response.answers[q.id], q.type)),
    ...(options.includeMetadata ? [
      response.metadata.ipAddress,
      response.metadata.device,
      response.metadata.country,
    ] : []),
  ]);

  const csv = Papa.unparse({ fields: headers, data: rows });
  downloadFile(csv, 'responses.csv', 'text/csv');
}
```

### 2. Excel Export
```typescript
import * as XLSX from 'xlsx';

async function exportToExcel(formId: string, options: ExportOptions) {
  const responses = await fetchResponses(formId, options.filters);
  const questions = await fetchQuestions(formId);

  // Create workbook
  const wb = XLSX.utils.book_new();

  // Responses sheet
  const responsesData = responses.map(r => ({
    'Response ID': r.id,
    'Submitted': r.completedAt,
    ...Object.fromEntries(
      questions.map(q => [q.title, formatAnswer(r.answers[q.id], q.type)])
    ),
  }));
  const ws1 = XLSX.utils.json_to_sheet(responsesData);
  XLSX.utils.book_append_sheet(wb, ws1, 'Responses');

  // Summary sheet
  const summaryData = questions.map(q => ({
    'Question': q.title,
    'Type': q.type,
    'Responses': countAnswers(responses, q.id),
    'Required': q.required ? 'Yes' : 'No',
  }));
  const ws2 = XLSX.utils.json_to_sheet(summaryData);
  XLSX.utils.book_append_sheet(wb, ws2, 'Summary');

  // Download
  XLSX.writeFile(wb, 'responses.xlsx');
}
```

