async function exportToPDF(responseId: string) {
  const response = await fetchResponse(responseId);
  const form = await fetchForm(response.formId);
  const questions = await fetchQuestions(response.formId);

  const blob = await pdf(
    <ResponsePDF response={response} questions={questions} form={form} />
  ).toBlob();

  downloadBlob(blob, `response-${responseId}.pdf`);
}
