### 4. JSON Export
```typescript
async function exportToJSON(formId: string, options: ExportOptions) {
  const responses = await fetchResponses(formId, options.filters);

  const exportData = {
    exportedAt: new Date().toISOString(),
    formId,
    totalResponses: responses.length,
    responses: responses.map(r => ({
      id: r.id,
      submittedAt: r.completedAt,
      answers: r.answers,
      ...(options.includeMetadata && { metadata: r.metadata }),
    })),
  };

  const json = JSON.stringify(exportData, null, 2);
  downloadFile(json, 'responses.json', 'application/json');
}
