### 8. Template Usage Flow
```typescript
async function useTemplate(templateId: string) {
  // Fetch template
  const template = await fetchTemplate(templateId);

  // Create new form from template
  const form = await createForm({
    title: `Copy of ${template.name}`,
    description: template.formSnapshot.description,
    settings: template.formSnapshot.settings,
  });

  // Add questions
  for (const question of template.formSnapshot.questions) {
    await addQuestion(form.id, {
      ...question,
      id: undefined, // Generate new ID
    });
  }

  // Apply theme if present
  if (template.formSnapshot.theme) {
    await updateForm(form.id, { themeId: null, customTheme: template.formSnapshot.theme });
  }

  // Increment usage count
  await incrementTemplateUsage(templateId);

