## Implementation

### Access Control Middleware
```typescript
// src/lib/access/middleware.ts
export async function checkFormAccess(
  formId: string,
  request: Request
): Promise<AccessResult> {
  const form = await getForm(formId);
  const settings = form.accessSettings;

  // Check if form is published
  if (form.status !== 'published') {
    return { allowed: false, reason: 'not_published' };
  }

  // Check schedule
  const now = new Date();
  if (settings.schedule?.openAt && now < new Date(settings.schedule.openAt)) {
    return { 
      allowed: false, 
      reason: 'not_open_yet',
      message: settings.schedule.beforeOpenMessage,
      opensAt: settings.schedule.openAt,
    };
  }
  if (settings.schedule?.closeAt && now > new Date(settings.schedule.closeAt)) {
    return { 
      allowed: false, 
      reason: 'closed',
      message: settings.schedule.afterCloseMessage,
    };
  }

  // Check response limit
  if (settings.maxResponses) {
    const count = await getResponseCount(formId);
    if (count >= settings.maxResponses) {
      return { 
        allowed: false, 
        reason: 'max_responses',
        message: settings.closedMessage,
      };
    }
  }

  // Check single response
  if (settings.singleResponse?.enabled) {
    const hasResponded = await checkPreviousResponse(formId, request);
    if (hasResponded) {
      return { 
        allowed: false, 
        reason: 'already_responded',
        existingResponseId: hasResponded.id,
        allowEdit: settings.singleResponse.allowEdit,
      };
    }
  }

  // Check password
  if (settings.passwordProtection?.enabled) {
    const providedPassword = getPasswordFromSession(request);
    if (!providedPassword) {
      return { allowed: false, reason: 'password_required' };
    }
    const valid = await verifyPassword(providedPassword, settings.passwordProtection.password);
    if (!valid) {
      return { allowed: false, reason: 'invalid_password' };
    }
  }

  // Check IP restrictions
  const ip = getClientIp(request);
  if (settings.ipRestrictions) {
    if (!isIpAllowed(ip, settings.ipRestrictions)) {
      return { allowed: false, reason: 'ip_blocked' };
    }
  }

  return { allowed: true };
}
```

