function PasswordGate({ formId, message }: PasswordGateProps) {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const result = await verifyFormPassword(formId, password);
    if (result.valid) {
      // Store in session and reload
      sessionStorage.setItem(`form_password_${formId}`, password);
      window.location.reload();
    } else {
      setError('Incorrect password');
    }
  };

  return (
    <div className="password-gate">
      <LockIcon className="w-12 h-12" />
      <h2>This form is password protected</h2>
      {message && <p>{message}</p>}

      <form onSubmit={handleSubmit}>
        <Input
