```typescript
// src/lib/integrations/oauth.ts
export async function initiateOAuth(provider: string, formId: string) {
  const state = encodeState({ provider, formId, userId: getCurrentUserId() });

  switch (provider) {
    case 'google':
      const googleUrl = new URL('https://accounts.google.com/o/oauth2/v2/auth');
      googleUrl.searchParams.set('client_id', process.env.GOOGLE_CLIENT_ID!);
      googleUrl.searchParams.set('redirect_uri', `${APP_URL}/api/integrations/callback`);
      googleUrl.searchParams.set('scope', 'https://www.googleapis.com/auth/spreadsheets');
      googleUrl.searchParams.set('response_type', 'code');
      googleUrl.searchParams.set('state', state);
      return googleUrl.toString();

    case 'slack':
      const slackUrl = new URL('https://slack.com/oauth/v2/authorize');
      slackUrl.searchParams.set('client_id', process.env.SLACK_CLIENT_ID!);
      slackUrl.searchParams.set('scope', 'incoming-webhook,chat:write');
      slackUrl.searchParams.set('redirect_uri', `${APP_URL}/api/integrations/callback`);
      slackUrl.searchParams.set('state', state);
      return slackUrl.toString();
  }
}

// Callback handler
export async function handleOAuthCallback(code: string, state: string) {
  const { provider, formId, userId } = decodeState(state);

  // Exchange code for tokens
  const tokens = await exchangeCodeForTokens(provider, code);

  // Save integration
  await saveIntegration(formId, provider, tokens);

  return { success: true, formId };
}
