### 9. Sync Jobs
```typescript
// Background job to sync integrations
async function syncGoogleSheets(integrationId: string) {
  const integration = await getIntegration(integrationId);
  const form = await getForm(integration.formId);
  const responses = await getResponsesSince(integration.formId, integration.lastSyncAt);

  const sheets = google.sheets({ version: 'v4', auth: integration.accessToken });

  // Prepare rows
  const rows = responses.map(response => 
    integration.mappings.map(m => response.answers[m.questionId]?.value || '')
  );

  // Append to sheet
  await sheets.spreadsheets.values.append({
    spreadsheetId: integration.spreadsheetId,
    range: `${integration.sheetName}!A:Z`,
    valueInputOption: 'USER_ENTERED',
    requestBody: { values: rows },
  });

  // Update last sync
  await updateIntegration(integrationId, { lastSyncAt: new Date() });
}
