function ResponsesTable({ formId, filters }: TableProps) {
  const { data, isLoading } = useQuery({
    queryKey: ['responses', formId, filters],
    queryFn: () => fetchResponses(formId, filters),
  });

  const columns = useMemo(() => [
    {
      id: 'select',
      header: ({ table }) => (
        <Checkbox
          checked={table.getIsAllRowsSelected()}
          onCheckedChange={table.toggleAllRowsSelected}
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={row.toggleSelected}
        />
      ),
    },
    {
      accessorKey: 'id',
      header: '#',
      cell: ({ row }) => row.index + 1,
    },
    {
      accessorKey: 'completedAt',
      header: 'Submitted',
      cell: ({ row }) => formatDate(row.original.completedAt),
    },
    // Dynamic columns for each question
    ...questions.map(q => ({
      accessorKey: `answers.${q.id}`,
      header: truncate(q.title, 30),
      cell: ({ row }) => <AnswerCell answer={row.original.answers[q.id]} />,
    })),
  ], [questions]);

  return (
    <DataTable
      columns={columns}
      data={data?.responses || []}
      pagination
      sorting
      filtering
    />
  );
}
