```typescript
// Using polling for simplicity
function useRealTimeResponses(formId: string) {
  return useQuery({
    queryKey: ['responses', formId],
    queryFn: () => fetchResponses(formId),
    refetchInterval: 30000, // Poll every 30s
  });
}

// Or WebSocket for true real-time
function useResponseWebSocket(formId: string) {
  useEffect(() => {
    const ws = new WebSocket(`wss://api.example.com/ws/forms/${formId}/responses`);

    ws.onmessage = (event) => {
      const newResponse = JSON.parse(event.data);
      queryClient.setQueryData(['responses', formId], (old) => ({
        ...old,
        responses: [newResponse, ...old.responses],
      }));
    };

    return () => ws.close();
  }, [formId]);
}
