```typescript
// src/stores/__tests__/formBuilderStore.test.ts
import { describe, it, expect, beforeEach } from 'vitest';
import { useFormBuilderStore } from '../formBuilderStore';
import { act, renderHook } from '@testing-library/react';

describe('Form Builder Store', () => {
  beforeEach(() => {
    const { result } = renderHook(() => useFormBuilderStore());
    act(() => result.current.reset());
  });

  describe('Question Management', () => {
    it('adds a question to the form', () => {
      const { result } = renderHook(() => useFormBuilderStore());

      act(() => {
        result.current.addQuestion({ type: 'short_text', title: 'Your name?' });
      });

      expect(result.current.questions).toHaveLength(1);
      expect(result.current.questions[0].type).toBe('short_text');
    });

    it('removes a question by id', () => {
      const { result } = renderHook(() => useFormBuilderStore());

      act(() => {
        result.current.addQuestion({ type: 'short_text', title: 'Q1' });
        result.current.addQuestion({ type: 'email', title: 'Q2' });
      });

      const questionId = result.current.questions[0].id;
      act(() => result.current.removeQuestion(questionId));

      expect(result.current.questions).toHaveLength(1);
      expect(result.current.questions[0].title).toBe('Q2');
    });

    it('updates question properties', () => {
      const { result } = renderHook(() => useFormBuilderStore());

      act(() => {
        result.current.addQuestion({ type: 'short_text', title: 'Old' });
      });

      const questionId = result.current.questions[0].id;
      act(() => {
        result.current.updateQuestion(questionId, { title: 'New Title' });
      });

      expect(result.current.questions[0].title).toBe('New Title');
    });

    it('reorders questions', () => {
      const { result } = renderHook(() => useFormBuilderStore());

      act(() => {
        result.current.addQuestion({ type: 'short_text', title: 'First' });
        result.current.addQuestion({ type: 'email', title: 'Second' });
        result.current.addQuestion({ type: 'number', title: 'Third' });
      });

      act(() => result.current.reorderQuestions(2, 0));

      expect(result.current.questions[0].title).toBe('Third');
      expect(result.current.questions[1].title).toBe('First');
    });

    it('duplicates a question', () => {
      const { result } = renderHook(() => useFormBuilderStore());

      act(() => {
        result.current.addQuestion({ type: 'short_text', title: 'Original' });
      });

      const questionId = result.current.questions[0].id;
      act(() => result.current.duplicateQuestion(questionId));

      expect(result.current.questions).toHaveLength(2);
      expect(result.current.questions[1].title).toBe('Original (copy)');
      expect(result.current.questions[1].id).not.toBe(questionId);
    });
  });

  describe('Selection State', () => {
    it('tracks selected question', () => {
      const { result } = renderHook(() => useFormBuilderStore());

      act(() => {
        result.current.addQuestion({ type: 'short_text', title: 'Q1' });
      });

      const questionId = result.current.questions[0].id;
      act(() => result.current.selectQuestion(questionId));

      expect(result.current.selectedQuestionId).toBe(questionId);
    });
  });

  describe('Undo/Redo', () => {
    it('undoes last action', () => {
      const { result } = renderHook(() => useFormBuilderStore());

      act(() => {
        result.current.addQuestion({ type: 'short_text', title: 'Q1' });
      });

      expect(result.current.questions).toHaveLength(1);

      act(() => result.current.undo());

      expect(result.current.questions).toHaveLength(0);
    });

    it('redoes undone action', () => {
      const { result } = renderHook(() => useFormBuilderStore());

      act(() => {
        result.current.addQuestion({ type: 'short_text', title: 'Q1' });
        result.current.undo();
        result.current.redo();
      });

      expect(result.current.questions).toHaveLength(1);
    });
  });
});
```

