```javascript
// public/embed.js
(function() {
  window.TypeformClone = {
    baseUrl: 'https://app.example.com',

    fullPage: function(formId, options = {}) {
      document.body.innerHTML = `
        <iframe src="${this.baseUrl}/f/${formId}?embed=true"
          style="position:fixed;top:0;left:0;width:100%;height:100%;border:0;"
          allow="camera;microphone">
        </iframe>
      `;
    },

    popup: function(formId, options = {}) {
      const button = document.createElement('button');
      button.textContent = options.buttonText || 'Open Form';
      button.style.cssText = `
        background: ${options.buttonColor || '#0066FF'};
        color: white;
        padding: 12px 24px;
        border: none;
        border-radius: 4px;
        cursor: pointer;
      `;

      button.onclick = () => this.openModal(formId, options);

      document.currentScript.parentNode.insertBefore(button, document.currentScript);
    },

    openModal: function(formId, options = {}) {
      const overlay = document.createElement('div');
      overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:9999;';

      const modal = document.createElement('div');
      modal.style.cssText = `
        position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);
        width:${options.width || 800}px;height:${options.height || 600}px;
        background:white;border-radius:8px;overflow:hidden;z-index:10000;
      `;

      modal.innerHTML = `
        <iframe src="${this.baseUrl}/f/${formId}?embed=true"
          style="width:100%;height:100%;border:0;"></iframe>
      `;

      overlay.onclick = () => { overlay.remove(); modal.remove(); };

      document.body.appendChild(overlay);
      document.body.appendChild(modal);
    },

    // More methods: slider, widget, etc.
  };
})();
