## File Upload Service
```typescript
// src/lib/upload/index.ts
interface UploadService {
  upload(file: File, options?: UploadOptions): Promise<UploadResult>;
  delete(fileId: string): Promise<void>;
  getSignedUrl(fileId: string): Promise<string>;
}

interface UploadResult {
  id: string;
  url: string;
  filename: string;
  size: number;
  mimeType: string;
}

// Local storage implementation
class LocalUploadService implements UploadService {
  async upload(file: File) {
    const formData = new FormData();
    formData.append('file', file);

    const response = await fetch('/api/upload', {
      method: 'POST',
      body: formData,
    });

    return response.json();
  }
}

// S3 implementation
class S3UploadService implements UploadService {
  async upload(file: File) {
    // Get presigned URL
    const { uploadUrl, fileId } = await fetch('/api/upload/presign', {
      method: 'POST',
      body: JSON.stringify({
        filename: file.name,
        contentType: file.type,
      }),
    }).then(r => r.json());

    // Upload directly to S3
    await fetch(uploadUrl, {
      method: 'PUT',
      body: file,
      headers: { 'Content-Type': file.type },
    });

    return { id: fileId, url: uploadUrl.split('?')[0] };
  }
}
```

