### File Upload Component
```typescript
export function FileUploadQuestion({ question, value, onChange }: QuestionProps) {
  const settings = question.settings as FileUploadSettings;
  const [files, setFiles] = useState<UploadedFile[]>(value || []);
  const [uploading, setUploading] = useState(false);

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    setUploading(true);

    for (const file of acceptedFiles) {
      // Validate
      if (settings.maxFileSize && file.size > settings.maxFileSize) {
        toast.error(`File too large: ${file.name}`);
        continue;
      }

      // Upload
      const result = await uploadService.upload(file);
      setFiles(prev => [...prev, result]);
    }

    setUploading(false);
    onChange(files);
  }, [settings]);

  return (
    <div className="file-upload">
      <Dropzone onDrop={onDrop} disabled={files.length >= (settings.maxFiles || 10)}>
        <UploadIcon />
        <p>Drag files here or click to browse</p>
        <p className="text-sm text-muted">
          Max {settings.maxFiles} files, {formatBytes(settings.maxFileSize)} each
        </p>
      </Dropzone>

      <FileList files={files} onRemove={handleRemove} />
    </div>
  );
}
```

### Signature Component
```typescript
export function SignatureQuestion({ question, value, onChange }: QuestionProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);

  const handlePointerDown = (e: React.PointerEvent) => {
    setIsDrawing(true);
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      ctx.beginPath();
      ctx.moveTo(e.nativeEvent.offsetX, e.nativeEvent.offsetY);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDrawing) return;
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      ctx.lineTo(e.nativeEvent.offsetX, e.nativeEvent.offsetY);
      ctx.stroke();
    }
  };

  const handleClear = () => {
    const ctx = canvasRef.current?.getContext('2d');
    ctx?.clearRect(0, 0, canvasRef.current!.width, canvasRef.current!.height);
    onChange(null);
  };

  const handleSave = () => {
    const dataUrl = canvasRef.current?.toDataURL('image/png');
    onChange(dataUrl);
  };

  return (
    <div className="signature-pad">
      <canvas
        ref={canvasRef}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={() => { setIsDrawing(false); handleSave(); }}
        className="border rounded touch-none"
      />
      <Button variant="outline" onClick={handleClear}>Clear</Button>
    </div>
  );
}
```

